SELECT '==DELETED ASSIGNS CON ARCHIVOS DE ESTUDIANTES EN CURSO 74 ==' as '';
SELECT f.id, f.itemid AS deleted_assign_id, u.id AS student_id, u.username AS cedula, u.firstname, u.lastname, f.filename, f.filesize, f.contenthash FROM isi_files f JOIN isi_user u ON u.id = f.userid WHERE f.component = 'assignsubmission_file' AND f.filename <> '.' AND f.contextid IN (SELECT id FROM isi_context WHERE contextlevel = 70 AND instanceid = 74) AND f.itemid IN (96, 97, 98, 99, 165, 257, 500, 65, 544, 735) ORDER BY f.itemid, u.id;
SELECT '==ACTIVIDADES VIVAS DEL GRUPO 660 (secci?n 924 / 9503) ==' as '';
SELECT cm.id AS cm_id, cm.section, s.name AS section_name, m.name AS module_type, cm.instance AS activity_id, a.name AS activity_name FROM isi_course_modules cm JOIN isi_course_sections s ON s.id = cm.section JOIN isi_modules m ON m.id = cm.module LEFT JOIN isi_assign a ON a.id = cm.instance WHERE cm.course = 74 AND cm.section = 924 AND cm.module = 1 ORDER BY cm.id;
SELECT '==GRUPOS 660 vs 661 (cual es el activo para 9503)==' as '';
SELECT id, name FROM isi_groups WHERE id IN (660, 661);
SELECT '==CUAL ES EL GMK_CLASS PARA GRUPO 660/661?==' as '';
SELECT id, name, gradecategoryid FROM isi_gmk_class WHERE id IN (9503, 9504);
SELECT '==GRADE ITEMS VIVOS EN CATEGORIA 924 (GRUPO 9503) ==' as '';
SELECT id, itemname, itemmodule, iteminstance, categoryid FROM isi_grade_items WHERE categoryid = 924 ORDER BY iteminstance;
SELECT '==GRADE ITEMS VIVOS EN CATEGORIA 925 (GRUPO 9504) ==' as '';
SELECT id, itemname, itemmodule, iteminstance, categoryid FROM isi_grade_items WHERE categoryid = 925 ORDER BY iteminstance;
